/**
 * WebGLBackdrop — the fixed full-screen background stage.
 *
 * This is the "tier A" replacement for the reference site's PixiJS stage: a real
 * WebGL full-screen pass, not a CSS approximation. It reproduces the four
 * behaviours that made the original stage read as alive:
 *
 *   1. TWO pre-composed collage sheets parallaxing at different depths
 *      (bg-lower.webp / bg-upper.webp, generated by scripts/build_backdrop.py)
 *   2. a pointer-driven RADIAL TWIST (the original used TwistFilter radius .2 /
 *      angle .15; we pushed it to .28/.35 because our sheets are sparser)
 *   3. animated GRAIN
 *   4. a fake POINT LIGHT that follows the pointer, plus a violet/magenta grade
 *
 * Everything is driven from one rAF loop writing uniforms only — no React state
 * per frame. `stop()`/`start()` let the 3D overlay freeze the stage.
 */

const VERT = `#version 300 es
in vec2 aPos;
out vec2 vUv;
void main() {
  vUv = aPos * 0.5 + 0.5;
  gl_Position = vec4(aPos, 0.0, 1.0);
}`;

const FRAG = `#version 300 es
precision highp float;
in vec2 vUv;
out vec4 outColor;

uniform vec2  uRes;
uniform vec2  uMouse;    // 0..1, smoothed
uniform float uTime;
uniform float uScroll;   // 0..1 page progress
uniform float uChroma;   // RGB-split amount, 0 at rest; driven by scrollFx
uniform sampler2D uTex0; // lower sheet
uniform sampler2D uTex1; // upper sheet

const float SHEET_ASPECT  = 2.0;    // both sheets are 4096x2048
const float PARALLAX      = 0.055;  // reference used .01 with much larger sheets
const float TWIST_RADIUS  = 0.28;
const float TWIST_ANGLE   = 0.35;

vec2 coverUv(vec2 uv, float zoom) {
  vec2 p = uv - 0.5;
  float viewAspect = uRes.x / max(uRes.y, 1.0);
  if (viewAspect > SHEET_ASPECT) {
    p.y *= SHEET_ASPECT / viewAspect;
  } else {
    p.x *= viewAspect / SHEET_ASPECT;
  }
  return p / zoom + 0.5;
}

vec3 layer(sampler2D tex, vec2 uv, float zoom, float depth) {
  vec2 t = coverUv(uv, zoom);
  t.y += uScroll * PARALLAX * depth;
  t.x += uScroll * PARALLAX * depth * 0.35;
  t += (uMouse - 0.5) * 0.02 * depth;
  return texture(tex, t).rgb;
}

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main() {
  // ---- pointer-centred radial twist -------------------------------------
  vec2 uv = vUv;
  float aspect = uRes.x / max(uRes.y, 1.0);
  vec2 d = uv - uMouse;
  d.x *= aspect;
  float dist = length(d);
  float infl = smoothstep(TWIST_RADIUS, 0.0, dist);
  float ang = TWIST_ANGLE * infl;
  float s = sin(ang), c = cos(ang);
  vec2 rd = vec2(d.x * c - d.y * s, d.x * s + d.y * c);
  rd.x /= aspect;
  vec2 tuv = mix(uv, uMouse + rd, 0.85);

  // ---- two parallaxing sheets ------------------------------------------
  float breathe = 1.0 + 0.012 * sin(uTime * 0.12);
  vec3 lower;
  vec3 upper;
  if (uChroma > 0.0008) {
    // A genuine chromatic aberration of the stage: each channel is sampled from
    // its own UV, offset radially from the frame centre. Branching keeps the
    // steady-state cost at two samples per frame — the split costs 6, and only
    // exists for the ~0.4s the burst lasts.
    vec2 ca = (tuv - 0.5) * uChroma;
    lower = vec3(
      layer(uTex0, tuv + ca, 1.06 * breathe, 1.0).r,
      layer(uTex0, tuv,      1.06 * breathe, 1.0).g,
      layer(uTex0, tuv - ca, 1.06 * breathe, 1.0).b
    );
    upper = vec3(
      layer(uTex1, tuv + ca, 1.28 * breathe, 0.42).r,
      layer(uTex1, tuv,      1.28 * breathe, 0.42).g,
      layer(uTex1, tuv - ca, 1.28 * breathe, 0.42).b
    );
  } else {
    lower = layer(uTex0, tuv, 1.06 * breathe, 1.0);   // fast / near
    upper = layer(uTex1, tuv, 1.28 * breathe, 0.42);  // slow / far
  }

  vec3 col = lower * 0.85 + upper * 0.55;
  col *= 0.22;                                  // stage sits at ~alpha .25 over #08060F
  col += vec3(0.031, 0.024, 0.059);             // the #08060F field itself

  // ---- violet/magenta + cyan grade (sampled from the splash) -----------
  float lum = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(col, vec3(lum), -0.35);             // push saturation
  col += vec3(0.10, 0.02, 0.16) * smoothstep(0.0, 0.55, lum);
  col += vec3(0.00, 0.05, 0.10) * smoothstep(0.45, 0.0, dist);

  // ---- fake point light that tracks the pointer -------------------------
  float lightDist = length((uv - uMouse) * vec2(aspect, 1.0));
  float light = smoothstep(0.55, 0.0, lightDist);
  col += vec3(0.30, 0.10, 0.42) * light * 0.55;
  col += vec3(0.10, 0.28, 0.40) * smoothstep(0.9, 0.15, lightDist) * 0.28;

  // ---- grain -------------------------------------------------------------
  float g = hash(gl_FragCoord.xy * 0.7 + fract(uTime) * 91.7);
  col += (g - 0.5) * 0.055;

  // ---- vignette ----------------------------------------------------------
  float vig = smoothstep(1.25, 0.25, length((uv - 0.5) * vec2(aspect, 1.0)) * 1.6);
  col *= mix(0.62, 1.0, vig);

  outColor = vec4(col, 1.0);
}`;

function compile(gl: WebGL2RenderingContext, type: number, src: string): WebGLShader {
  const sh = gl.createShader(type)!;
  gl.shaderSource(sh, src);
  gl.compileShader(sh);
  if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(sh);
    gl.deleteShader(sh);
    throw new Error(`shader compile failed: ${log}`);
  }
  return sh;
}

export type BackdropState = { ok: boolean; error?: string; frames: number };

export class Backdrop {
  private gl: WebGL2RenderingContext | null = null;
  private program: WebGLProgram | null = null;
  private loc: Record<string, WebGLUniformLocation | null> = {};
  private textures: WebGLTexture[] = [];
  private raf = 0;
  private running = false;
  private start = performance.now();
  private mouse = { x: 0.62, y: 0.38 };
  private target = { x: 0.62, y: 0.38 };
  private scroll = 0;
  private scrollTarget = 0;
  private chroma = 0;
  private disposeResize?: () => void;
  private disposePointer?: () => void;
  private disposed = false;
  public state: BackdropState = { ok: false, frames: 0 };

  constructor(private canvas: HTMLCanvasElement, private sources: [string, string]) {}

  async init(): Promise<BackdropState> {
    const gl = this.canvas.getContext('webgl2', {
      alpha: false,
      antialias: false,
      powerPreference: 'high-performance',
      premultipliedAlpha: false,
    });
    if (!gl) {
      this.state = { ok: false, error: 'WebGL2 unavailable', frames: 0 };
      return this.state;
    }
    this.gl = gl;

    try {
      const vs = compile(gl, gl.VERTEX_SHADER, VERT);
      const fs = compile(gl, gl.FRAGMENT_SHADER, FRAG);
      const program = gl.createProgram()!;
      gl.attachShader(program, vs);
      gl.attachShader(program, fs);
      gl.linkProgram(program);
      if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
        throw new Error(`program link failed: ${gl.getProgramInfoLog(program)}`);
      }
      this.program = program;
      for (const n of ['uRes', 'uMouse', 'uTime', 'uScroll', 'uChroma', 'uTex0', 'uTex1']) {
        this.loc[n] = gl.getUniformLocation(program, n);
      }

      const buf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
      const aPos = gl.getAttribLocation(program, 'aPos');
      gl.enableVertexAttribArray(aPos);
      gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

      gl.useProgram(program);
      const [a, b] = await Promise.all([this.loadTexture(this.sources[0]), this.loadTexture(this.sources[1])]);
      if (this.disposed) {
        // React StrictMode mounts twice in dev: never resurrect a disposed stage.
        gl.deleteTexture(a);
        gl.deleteTexture(b);
        return this.state;
      }
      this.textures = [a, b];
      gl.uniform1i(this.loc.uTex0, 0);
      gl.uniform1i(this.loc.uTex1, 1);

      this.resize();
      this.bindEvents();
      this.state.ok = true;
      this.play();
    } catch (err) {
      this.state = { ok: false, error: String(err), frames: 0 };
    }
    return this.state;
  }

  private loadTexture(url: string): Promise<WebGLTexture> {
    const gl = this.gl!;
    const tex = gl.createTexture()!;
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        gl.bindTexture(gl.TEXTURE_2D, tex);
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        resolve(tex);
      };
      img.onerror = () => reject(new Error(`failed to load ${url}`));
      img.src = url;
    });
  }

  private resize = () => {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.floor(window.innerWidth * dpr);
    const h = Math.floor(window.innerHeight * dpr);
    if (this.canvas.width !== w || this.canvas.height !== h) {
      this.canvas.width = w;
      this.canvas.height = h;
    }
    this.gl?.viewport(0, 0, w, h);
  };

  private bindEvents() {
    const onResize = () => this.resize();
    window.addEventListener('resize', onResize);
    this.disposeResize = () => window.removeEventListener('resize', onResize);

    const onPointer = (e: PointerEvent) => {
      this.target.x = e.clientX / window.innerWidth;
      this.target.y = 1 - e.clientY / window.innerHeight;
    };
    window.addEventListener('pointermove', onPointer, { passive: true });
    this.disposePointer = () => window.removeEventListener('pointermove', onPointer);
  }

  setScroll(progress: number) {
    this.scrollTarget = progress;
  }

  /** RGB-split amount for the full-screen pass. 0 = off (default). */
  setChroma(v: number) {
    this.chroma = Math.max(0, Math.min(v, 0.12));
  }

  play() {
    if (this.disposed || this.running) return;
    this.running = true;
    const loop = () => {
      if (!this.running) return;
      const gl = this.gl;
      const program = this.program;
      if (gl && program) {
        // exponential smoothing — pointer and scroll never snap
        this.mouse.x += (this.target.x - this.mouse.x) * 0.06;
        this.mouse.y += (this.target.y - this.mouse.y) * 0.06;
        this.scroll += (this.scrollTarget - this.scroll) * 0.08;

        gl.useProgram(program);
        gl.uniform2f(this.loc.uRes, this.canvas.width, this.canvas.height);
        gl.uniform2f(this.loc.uMouse, this.mouse.x, this.mouse.y);
        gl.uniform1f(this.loc.uTime, (performance.now() - this.start) / 1000);
        gl.uniform1f(this.loc.uScroll, this.scroll);
        // Written straight through: scrollFx.ts authors the envelope, including
        // the hard steps that make the burst read as a glitch. Smoothing it here
        // would round off exactly the frames that carry the effect.
        gl.uniform1f(this.loc.uChroma, this.chroma);
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.textures[0]);
        gl.activeTexture(gl.TEXTURE1);
        gl.bindTexture(gl.TEXTURE_2D, this.textures[1]);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
        this.state.frames++;
      }
      this.raf = requestAnimationFrame(loop);
    };
    this.raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    cancelAnimationFrame(this.raf);
  }

  dispose() {
    this.disposed = true;
    this.stop();
    this.disposeResize?.();
    this.disposePointer?.();
    const gl = this.gl;
    if (gl) {
      this.textures.forEach((t) => gl.deleteTexture(t));
      if (this.program) gl.deleteProgram(this.program);
    }
  }
}
